function getLastEntryInMultiHeaderValue (headerValue) {
  // we use the last one if the header is set more than once
  const lastIndex = headerValue.lastIndexOf(',')
  return lastIndex === -1 ? headerValue.trim() : headerValue.slice(lastIndex + 1).trim()
}

tool_input.new_string:
function getLastEntryInMultiHeaderValue (headerValue) {
  // we use the last one if the header is set more than once
  const lastIndex = headerValue.lastIndexOf(',')
  return lastIndex === -1 ? headerValue.trim() : headerValue.slice(lastIndex + 1).trim()
}

// The `x-forwarded-*` headers may only be honoured when the peer that sent them
// is itself a trusted proxy, otherwise any client can spoof `host`/`protocol`.
// `ip` and `ips` do not need this gate: `proxyAddr.all` already walks the
// forwarded chain with the trust function and stops at the first untrusted hop.
function isTrustedProxy (req, proxyFn) {
  // `trustProxy: true` compiles to a null function, meaning trust every hop
  if (proxyFn === null) {
    return true
  }
  const remoteAddress = req.socket?.remoteAddress
  return remoteAddress !== undefined && proxyFn(remoteAddress, 0) === true
}
